#!/usr/bin/env python3
"""Run from project root: python3 fix_auth_ui.py"""
import base64, os, sys

if not os.path.exists("app"):
    print("Run from project root"); sys.exit(1)

FILES = {
    "app/page.tsx": "",
    "components/AuthGate.tsx": "",
    "components/BorrowPage.tsx": "",
    "components/LanguageSelector.tsx": "",
    "components/inspection/CryptographicProof.tsx": "",
    "components/inspection/UnderwritingEngine.tsx": "",
    "app/auth/signin/page.tsx": "",
}

for path, enc in FILES.items():
    d = os.path.dirname(path)
    if d: os.makedirs(d, exist_ok=True)
    content = base64.b64decode(enc).decode("utf-8")
    open(path, "w", encoding="utf-8", newline="\n").write(content)
    print(f"WRITTEN  {path}  ({len(content.splitlines())} lines)")

print("""
Done. Run:
  npm run build
  git add -A
  git commit -m "feat: auth gate, billboard borrow, functional i18n, verification prominence"
  git push origin main
""")
